{
  "name": "builder_all_pairs_clamped",
  "intuition": "all pairs with clamped objective difference to enforce a margin constraint",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
    "weight_family": "uniform_none",
    "constraint_family": "clamp_margin"
  },
  "operators_used": [
    "all_pairs",
    "clamp"
  ],
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    margin = 0.1\n    diff = objective[:, :, None] - objective[:, None, :]\n    mask = diff < -margin\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    # Clamp the difference so pairs meet margin constraint\n    clamped_diff = diff[b_idx, winner_idx, loser_idx].clamp(max=-margin)\n    # Use clamped_diff as weights (non-negative after negation)\n    weights = (-clamped_diff).relu()\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weights, meta={'builder': 'all_pairs_clamped'})\n"
}

{
  "name": "builder_all_pairs_thresholded_000",
  "intuition": "This builder filters pairs based on a threshold on the objective differences, aiming to focus on meaningful pairs and reduce noise. Threshold is set to a configurable value for flexibility.",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
    "weight_family": "uniform_none",
    "constraint_family": "none"
  },
  "operators_used": ["all_pairs"],
  "implementation_hint": {
    "expects": ["objective", "log_prob"],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    gap_threshold = float(extra.get('gap_threshold', 0.2))\n    mask = (objective[:, :, None] - objective[:, None, :]) >= gap_threshold\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    max_pairs = int(extra.get('max_pairs', 256))\n    total_pairs = b_idx.shape[0]\n    if total_pairs > max_pairs:\n        topk_values, topk_indices = (b_idx, b_idx).topk(k=max_pairs, dim=0, largest=True)\n        b_idx = b_idx[topk_indices]\n        winner_idx = winner_idx[topk_indices]\n        loser_idx = loser_idx[topk_indices]\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs_thresholded'})\n"
}

