{
  "name": "builder_rank_band_disagree_002",
  "intuition": "pairs chosen from a narrow rank band with disagreement weighting",
  "hyperparams": {
    "geometry_family": "rank_band_pairs",
    "cap_family": "capped_threshold",
    "weight_family": "disagreement_weighted",
    "constraint_family": "none"
  },
  "operators_used": [
    "topk",
    "abs",
    "diff",
    "nonzero"
  ],
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    batch_size, n = objective.shape\n    # Compute ranks per instance\n    ranks = objective.argsort(dim=1).argsort(dim=1)\n    # Define narrow rank band pairs: winner rank exactly 1 better than loser rank\n    winner_rank = ranks\n    loser_rank = ranks\n    rank_diff = winner_rank[:, :, None] - loser_rank[:, None, :]\n    mask = rank_diff == 1\n    # Mask to valid pairs where objective is lower for winner\n    better_mask = objective[:, :, None] < objective[:, None, :]\n    final_mask = mask & better_mask\n    b_idx, winner_idx, loser_idx = final_mask.nonzero(as_tuple=True)\n    # Compute disagreement weight as absolute difference of log_prob logits\n    log_prob = feature_cache['log_prob']\n    log_prob_diff = (log_prob[b_idx, winner_idx] - log_prob[b_idx, loser_idx]).abs()\n    max_weight = 2.0\n    weights = torch.clamp(log_prob_diff, max=max_weight)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weights, meta={'builder': 'rank_band_disagree'})\n"
}

{
  "name": "builder_rank_band_pairs_002",
  "intuition": "pairs within a rank band to focus on near competitors",
  "hyperparams": {
    "geometry_family": "rank_band",
    "cap_family": "capped_band",
    "weight_family": "gap_weighted",
    "constraint_family": "none"
  },
  "operators_used": [
    "rank_sort",
    "band_mask"
  ],
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    batch_size, n_items = objective.shape\n    ranks = objective.argsort(dim=1, descending=False)\n    inv_ranks = torch.zeros_like(ranks)\n    inv_ranks.scatter_(1, ranks, torch.arange(n_items, device=objective.device).unsqueeze(0).expand(batch_size, -1))\n    rank_i = inv_ranks.unsqueeze(2)  # shape (B, N, 1)\n    rank_j = inv_ranks.unsqueeze(1)  # shape (B, 1, N)\n    band_width = int(extra.get('band_width', 3))\n    band_mask = (rank_j > rank_i) & ((rank_j - rank_i) <= band_width)\n    better_mask = (objective[:, :, None] < objective[:, None, :])\n    mask = band_mask & better_mask\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    gap = (objective[b_idx, loser_idx] - objective[b_idx, winner_idx]).clamp(min=0)\n    weight = gap\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'rank_band_pairs'})\n"
}

{
  "name": "builder_all_pairs_clamped",
  "intuition": "all pairs with explicit clamp constraint to limit pairwise differences",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "clamped_diff",
    "weight_family": "uniform_none",
    "constraint_family": "clamp_diff"
  },
  "operators_used": [
    "all_pairs",
    "clamp"
  ],
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    diff = objective[:, :, None] - objective[:, None, :]\n    mask = diff < 0\n    # Clamp differences to max -0.5 to enforce a tie zone-like constraint\n    clamped_diff = diff.clamp(max=-0.5)\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    # Filter pairs where clamped difference is significant (less than -0.1)\n    valid_mask = clamped_diff[b_idx, winner_idx, loser_idx] < -0.1\n    b_idx = b_idx[valid_mask]\n    winner_idx = winner_idx[valid_mask]\n    loser_idx = loser_idx[valid_mask]\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs_clamped'})\n"
}

{
  "name": "sampled_pairs_threshold_005",
  "intuition": "Adjusted gap threshold to be more selective in pairing, ensuring only significantly better pairs are considered, which improves preference quality without overwhelming the system. Increased max_pairs cap to handle larger pair sets efficiently.",
  "hyperparams": {
    "geometry_family": "sampled_pairs",
    "cap_family": "budget_sample",
    "weight_family": "uniform_none",
    "constraint_family": "budget_clamp"
  },
  "operators_used": ["sampled_pairs"],
  "implementation_hint": {
    "expects": ["objective", "log_prob"],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    gap_threshold = float(extra.get('gap_threshold', 0.05))\n    max_pairs = int(extra.get('max_pairs', 8192))\n    gap = objective[:, None, :] - objective[:, :, None]\n    mask = gap > gap_threshold\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    if b_idx.numel() > max_pairs:\n        scores = gap[b_idx, winner_idx, loser_idx]\n        keep = torch.topk(scores, k=max_pairs, largest=True, sorted=False).indices\n        b_idx = b_idx[keep]\n        winner_idx = winner_idx[keep]\n        loser_idx = loser_idx[keep]\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'sampled_pairs', 'max_pairs': max_pairs})\n"
}

