  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    gap_threshold = float(extra.get('gap_threshold', 0.05))\n    tie_zone = float(extra.get('tie_zone', 0.1))\n    max_pairs = int(extra.get('max_pairs', 8192))\n    gap = objective[:, None, :] - objective[:, :, None]\n    mask = gap > gap_threshold\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    if b_idx.numel() > 0:\n        filtered_gap = gap[b_idx, winner_idx, loser_idx]\n        clamped_gap = filtered_gap.clamp(min=tie_zone)\n        valid_mask = clamped_gap > tie_zone\n        b_idx = b_idx[valid_mask]\n        winner_idx = winner_idx[valid_mask]\n        loser_idx = loser_idx[valid_mask]\n        if b_idx.numel() > max_pairs:\n            scores = gap[b_idx, winner_idx, loser_idx]\n            keep = scores.topk(k=max_pairs, largest=True, sorted=False).indices\n            b_idx = b_idx[keep]\n            winner_idx = winner_idx[keep]\n            loser_idx = loser_idx[keep]\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'sampled_pairs_tiezone_filter', 'max_pairs': max_pairs})"
