{
  "name": "pairwise_simple_pref_tiezone_clamp",
  "intuition": "Construct pairwise preferences with tie-zone constraint to filter out overly similar pairs, ensuring robust preference signals",
  "hyperparams": {
    "geometry_family": "pairwise_metric",
    "cap_family": "topk_cap",
    "weight_family": "uniform",
    "constraint_family": "tiezone_filter"
  },
  "operators_used": ["clamp", "nonzero", "logical_and"],
  "implementation_hint": {
    "expects": ["objective", "log_prob"],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    diff = objective[:, :, None] - objective[:, None, :]\n    prefer_mask = diff < 0\n    abs_diff = diff.abs()\n    tiezone_threshold = 0.01\n    tiezone_mask = abs_diff > tiezone_threshold\n    combined_mask = prefer_mask & tiezone_mask\n    b_idx, winner_idx, loser_idx = combined_mask.nonzero(as_tuple=True)\n    max_pairs = 8192\n    if b_idx.numel() > max_pairs:\n        selected = (b_idx.new_tensor(range(max_pairs)))\n        b_idx = b_idx[selected]\n        winner_idx = winner_idx[selected]\n        loser_idx = loser_idx[selected]\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'pairwise_simple_pref_tiezone_clamp'})"
}

{
  "name": "pairwise_disagreement_neighborhood",
  "intuition": "Pairs formed around local objective rank neighbors with disagreement-driven selection and exponentially decayed weights to emphasize informative near-ties.",
  "hyperparams": {
    "geometry_family": "disagreement_neighborhood",
    "cap_family": "exponential_decay",
    "weight_family": "disagreement_weighted",
    "constraint_family": "none"
  },
  "operators_used": [
    "argsort",
    "scatter",
    "broadcast_sub",
    "exp",
    "logical_and"
  ],
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']  # shape (B, N)\n    B, N = objective.shape\n    # Compute ranks (0 is best)\n    ranks = objective.argsort(dim=1, descending=False)  # (B, N)\n    inv_ranks = torch.zeros_like(ranks)\n    inv_ranks.scatter_(1, ranks, torch.arange(N, device=objective.device).unsqueeze(0).expand(B, -1))  # inverse rank map\n\n    # Pair candidates: only neighbor items differing by at most 2 ranks\n    rank_i = inv_ranks.unsqueeze(2)  # (B, N, 1)\n    rank_j = inv_ranks.unsqueeze(1)  # (B, 1, N)\n    neighbor_mask = (rank_j > rank_i) & ((rank_j - rank_i) <= 2)\n\n    # Preference mask where i strictly better than j\n    better_mask = objective[:, :, None] < objective[:, None, :]\n    combined_mask = neighbor_mask & better_mask\n\n    b_idx, winner_idx, loser_idx = combined_mask.nonzero(as_tuple=True)\n\n    # Compute disagreement as negative absolute difference in objective (near ties preferred)\n    gap = (objective[b_idx, loser_idx] - objective[b_idx, winner_idx]).clamp(min=0)\n    # Weight: exponential decay emphasizing smaller gaps (more informative near ties)\n    weight = torch.exp(-5.0 * gap)\n\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'pairwise_disagreement_neighborhood'})"
}

{
  "name": "sampled_pairs_topk_budget",
  "intuition": "Use a top-k budget cap per batch instance to limit pair complexity while maintaining selective pairing from sampled pairs.",
  "hyperparams": {
    "geometry_family": "sampled_pairs",
    "cap_family": "topk_per_instance",
    "weight_family": "uniform_none",
    "constraint_family": "budget_clamp"
  },
  "operators_used": [
    "sampled_pairs"
  ],
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    gap_threshold = float(extra.get('gap_threshold', 0.05))\n    max_pairs_per_instance = int(extra.get('max_pairs_per_instance', 256))\n    gap = objective[:, None, :] - objective[:, :, None]\n    mask = gap > gap_threshold\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    batch_size = objective.size(0)\n    if b_idx.numel() > 0:\n        pair_scores = gap[b_idx, winner_idx, loser_idx]\n        keep_mask = torch.zeros_like(b_idx, dtype=torch.bool)\n        for b in range(batch_size):\n            batch_mask = (b_idx == b)\n            if batch_mask.any():\n                scores_batch = pair_scores[batch_mask]\n                _, topk_indices = torch.topk(scores_batch, k=min(max_pairs_per_instance, scores_batch.size(0)), largest=True, sorted=False)\n                keep_mask[batch_mask.nonzero(as_tuple=True)[0][topk_indices]] = True\n        b_idx = b_idx[keep_mask]\n        winner_idx = winner_idx[keep_mask]\n        loser_idx = loser_idx[keep_mask]\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'sampled_pairs_topk_budget', 'max_pairs_per_instance': max_pairs_per_instance})"
}

