  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']  # (B, N)\n    log_prob = feature_cache['log_prob']  # (B, N)\n    B, N = objective.shape\n    lp_i = log_prob.unsqueeze(2)  # (B, N, 1)\n    lp_j = log_prob.unsqueeze(1)  # (B, 1, N)\n    disagreement = (lp_i - lp_j).abs()  # (B, N, N)\n    eye = torch.eye(N, device=objective.device, dtype=torch.bool).unsqueeze(0)  # (1, N, N)\n    disagreement.masked_fill_(eye, float('-inf'))\n    mask = (objective.unsqueeze(2) < objective.unsqueeze(1))  # (B, N, N), winner objective better\n    mask = mask & (disagreement > 0)\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    weights = (log_prob[b_idx, winner_idx] - log_prob[b_idx, loser_idx]).abs()\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weights, meta={'builder': 'disagreement_sparse_neighborhood_simple'})"
