{
  "name": "objective_diff_topk_cap",
  "intuition": "Limits pairwise preferences to top-k largest improvements per anchor, ensuring a capped budget and focused pairs.",
  "hyperparams": {
    "geometry_family": "Euclidean",
    "cap_family": "topk_per_anchor",
    "weight_family": "clamped_binary",
    "constraint_family": "tiezone_filter"
  },
  "operators_used": [
    "compute_difference",
    "mask_better_pairs",
    "clamp",
    "tiezone_filter",
    "topk"
  ],
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    diff = objective[:, :, None] - objective[:, None, :]\n    tiezone_threshold = 1e-3\n    mask = diff < -tiezone_threshold\n    batch_size, n = objective.shape\n    # For each anchor (winner index), consider losing indices\n    # We reshape diff and mask to (batch_size, n, n)\n    import torch\n    diff_masked = diff.clone()\n    diff_masked[~mask] = float('inf')\n    # For each winner_idx (dimension 2), get top k losers with largest negative diff\n    k = 5\n    topk_vals, topk_idx = torch.topk(-diff_masked, k=k, dim=2, largest=True, sorted=False)\n    # Prepare indices for batch and winner\n    b_idx = torch.arange(batch_size, device=diff.device)[:, None, None].expand(batch_size, n, k).reshape(-1)\n    winner_idx = torch.arange(n, device=diff.device)[None, :, None].expand(batch_size, n, k).reshape(-1)\n    loser_idx = topk_idx.reshape(-1)\n    weights = topk_vals.reshape(-1).clamp(min=0, max=1.0)\n    # Filter out invalid pairs where weight is zero or inf\n    valid = weights > 0\n    b_idx = b_idx[valid]\n    winner_idx = winner_idx[valid]\n    loser_idx = loser_idx[valid]\n    weights = weights[valid]\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weights, meta={'builder': 'objective_diff_topk_cap'})"
}

