  "intuition": "Shift to a hinge-loss paradigm focusing on rank differences as the primary signal, normalized by the absolute delta_rank plus a small offset for numerical stability. This approach enforces a margin-based separation on the normalized log-probability difference scaled by the rank gap, encouraging the model to respect ranking preferences robustly even with variable rank distances.",
  "pseudocode": "rank_gap = abs(delta_rank) + epsilon\nnormalized_logprob_diff = (log_prob_w - log_prob_l) / rank_gap\nmargin_violation = relu(margin - normalized_logprob_diff)\nweighted_loss = weight * margin_violation\nloss = mean(weighted_loss)\nreturn loss",
  "hyperparams": {
    "paradigm_family": "pairwise_hinge",
    "signal_family": "delta_rank",
    "link_family": "relu",
    "agg_family": "mean",
    "constraint_family": "normalization_rank_gap"
  },
  "operators_used": ["abs", "add", "div", "mul", "relu", "mean", "sub"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "delta_rank"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    eps = 1e-8\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    delta_rank = batch['delta_rank']\n    weight = batch.get('weight', lpw.new_ones(lpw.shape))\n    margin = float(extra.get('margin', 1.0))\n\n    rank_gap = ops.add(ops.abs(delta_rank), eps)  # avoid division by zero\n    norm_diff = ops.div(ops.sub(lpw, lpl), rank_gap)\n    margin_violation = ops.relu(ops.sub(margin, norm_diff))\n\n    loss_vec = ops.mul(weight, margin_violation)\n    return ops.mean(loss_vec)"
}

{
  "name": "pairwise_cost_gap_normalized_logsigmoid",
  "intuition": "This loss function leverages the cost gap as a normalization factor to stabilize training. By applying logsigmoid to the scaled difference in log probabilities, and normalizing by the absolute cost gap, it encourages the model to assign higher probability to better (lower cost) options while maintaining scale invariance, making the training more robust to variations in cost magnitude.",
  "pseudocode": "loss = mean(-logsigmoid(alpha * scale * (log_prob_w - log_prob_l) - lambda * cost_gap) / (abs(cost_gap) + epsilon))",
  "hyperparams": {
    "paradigm_family": "pairwise_margin",
    "signal_family": "cost_gap",
    "link_family": "logsigmoid",
    "agg_family": "mean",
    "constraint_family": "normalization_scale_invariant",
    "other_hparams": "optional"
  },
  "operators_used": ["logsigmoid", "clamp", "mean", "abs", "add"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_a", "cost_b"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))\n    scale = float(extra.get('hyperparams', {}).get('scale', 1.9542595038636554))\n    cost_a = batch['cost_a']\n    cost_b = batch['cost_b']\n    gap = (cost_b - cost_a).detach()\n    x = alpha * scale * (lpw - lpl) - 1.0 * gap\n    x = ops.clamp(x, -20.0, 20.0)\n    loss = -ops.logsigmoid(x)\n    norm = ops.abs(gap) + 1e-6\n    loss = loss / norm\n    if weight is not None:\n        loss = loss * weight\n    return ops.mean(loss)"
}

