{
  "name": "loss_tanh_delta_regret_ranking_mean_fixed",
  "intuition": "Keep the pairwise ranking loss based on a tanh activation on normalized regret differences, but aggregate using a simple mean rather than a weighted sum, to evenly penalize all pairs regardless of weight. Fix clamp usage with safe eps and float literals.",
  "pseudocode": "eps = 1e-8\nnorm_delta = zscore(delta_regret)\nscore_diff = log_prob_w - log_prob_l\npenalty = tanh(norm_delta * score_diff)\nsmooth_penalty = (1 - penalty) / 2\nloss = mean(smooth_penalty)",
  "hyperparams": {
    "paradigm_family": "pairwise_ranking",
    "signal_family": "delta_regret",
    "link_family": "tanh",
    "agg_family": "mean",
    "constraint_family": "zscore_normalization"
  },
  "operators_used": ["zscore", "tanh", "sub", "mul", "add", "div", "mean"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "delta_regret"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    eps = 1e-8\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch['weight']\n    delta_regret = batch['delta_regret']\n    norm_delta = ops.zscore(delta_regret)\n    score_diff = ops.sub(lpw, lpl)\n    pen = ops.mul(norm_delta, score_diff)\n    pen = ops.tanh(pen)\n    smooth_loss = ops.div(ops.sub(1.0, pen), 2.0)  # scaled to [0,1]\n    loss = ops.mean(smooth_loss)\n    return loss\n"
}

