  "intuition": "This loss uses the cost_gap signal to enforce a margin between pairs, applying logsigmoid to the scaled difference to emphasize preference correctness. The weighted median aggregation provides robustness to outliers, and normalization ensures scale invariance. It effectively penalizes pairs where the cost gap indicates the winner is not sufficiently better, promoting correct ordering with scale-invariant margins.",
  "pseudocode": "loss = median(weight * (-logsigmoid(clamp(alpha * scale * (log_prob_w - log_prob_l) - 0.1 * cost_gap, -20, 20))) / (abs(cost_gap) + epsilon))",
  "hyperparams": {
    "paradigm_family": "pairwise_margin",
    "signal_family": "cost_gap",
    "link_family": "logsigmoid",
    "agg_family": "weighted_median",
    "constraint_family": "normalization_scale_invariant"
  },
  "operators_used": ["logsigmoid", "clamp", "abs", "median", "mul", "div", "sub"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', ops.ones_like(lpw))\n    cost_gap = batch['cost_gap'].detach()\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))\n    scale = float(extra.get('hyperparams', {}).get('scale', 2.0))\n    margin = 0.1\n    x = ops.sub(ops.mul(alpha * scale, ops.sub(lpw, lpl)), ops.mul(margin, cost_gap))\n    x = ops.clamp(x, -20.0, 20.0)\n    raw_loss = -ops.logsigmoid(x)\n    normalization = ops.abs(cost_gap) + 1e-8\n    weighted_loss = raw_loss * weight / normalization\n    loss = ops.median(weighted_loss)\n    return loss"
}

