{
  "name": "pairwise_cost_gap_logsigmoid_diff_norm",
  "intuition": "Fixed median not supported by replacing with weighted mean; preserve original logsigmoid difference, weighted by cost_gap squared and normalized.",
  "pseudocode": "loss = sum(weight * (-logsigmoid(alpha*scale*(log_prob_w - log_prob_l)) + logsigmoid(-alpha*scale*(log_prob_w - log_prob_l))) * cost_gap^2) / sum(weight * cost_gap^2)",
  "hyperparams": {
    "paradigm_family": "pairwise_margin",
    "signal_family": "cost_gap",
    "link_family": "logsigmoid_diff",
    "agg_family": "weighted_mean",
    "constraint_family": "normalization_scale_invariant",
    "other_hparams": "alpha, scale"
  },
  "operators_used": ["logsigmoid", "mul", "add", "sub", "div", "sum", "neg"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    eps = 1e-8\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', lpw.new_ones(lpw.shape))\n    cost_gap = batch['cost_gap'].detach()\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))\n    scale = float(extra.get('hyperparams', {}).get('scale', 2.0))\n    margin = ops.mul(alpha * scale, ops.sub(lpw, lpl))\n    term_pos = ops.neg(ops.logsigmoid(margin))\n    term_neg = ops.logsigmoid(ops.neg(margin))\n    combined = ops.add(term_pos, term_neg)\n    cost_gap_sq = ops.mul(cost_gap, cost_gap)\n    weighted = ops.mul(weight, ops.mul(combined, cost_gap_sq))\n    sum_weights = ops.sum(ops.mul(weight, cost_gap_sq)) + eps\n    loss = ops.sum(weighted) / sum_weights\n    return loss"
}

